def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Find all markers
    from collections import defaultdict
    markers = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                markers[(r,c)] = grid[r][c]

    # Categorize markers by value
    value_a = defaultdict(list)  # column indices for row 0
    value_b_rows = defaultdict(list)  # row indices for column 0
    value_c = defaultdict(list)  # (r, c) tuples for elsewhere

    for (r,c), v in markers.items():
        if r == 0:
            value_a[v].append(c)
        elif c == 0:
            value_b_rows[v].append(r)
        else:
            value_c[v].append((r, c))

    # Copy markers first
    for (r,c), v in markers.items():
        result[r][c] = v

    # For each value, pair markers properly
    all_values = sorted(set(list(value_a.keys())) | set(list(value_b_rows.keys())))

    for v in all_values:
        cols_a = value_a[v]
        rows_b = value_b_rows[v]
        cells_c = value_c[v]

        num_a = len(cols_a)
        num_b = len(rows_b)
        num_c = len(cells_c)
        num_bc = num_b + num_c

        # Rebuild paired lists with original structure
        paired_a = [(0, c) for c in sorted(cols_a)]
        paired_b = [(r, 0) for r in sorted(rows_b)]
        paired_c = [(r, c) for (r, c) in sorted(cells_c, key=lambda x: x[0])]

        num_pair = min(num_a, num_bc)

        for i in range(num_pair):
            (r0, c0) = paired_a[i]

            if i < num_b:
                # Pair with Type B
                target = paired_b[i]
                r_b, c_b = target
                # Horizontal from (r_b, 0) toward column c0
                for c in range(min(c_b, c0), max(c_b, c0) + 1):
                    result[r_b][c] = v
                # Vertical from (0, c0) toward row r_b
                for r in range(1, r_b + 1):
                    result[r][c0] = v
            else:
                # Pair with Type C (i - num_b)
                target = paired_c[i - num_b]
                r_c, c_c = target
                # Horizontal from (r_c, c_c) toward column c0
                for c in range(min(c_c, c0), max(c_c, c0) + 1):
                    result[r_c][c] = v
                # Vertical from (0, c0) toward row r_c
                for r in range(1, r_c + 1):
                    result[r][c0] = v

        # For Type A markers with no matching Type B/C (only when num_a > num_bc)
        if num_a > num_bc:
            for i in range(num_bc, num_a):
                c = paired_a[i][1]
                result[0][c] = v
                for r in range(1, h):
                    result[r][c] = v

    return result

